-- Eardle database initialization.
-- PostgreSQL runs this file automatically on first boot when the data volume is empty.
-- Creates all tables and seeds exercise data — no manual steps required.

SET statement_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET client_min_messages = warning;

-- Schema

CREATE TABLE "admin_users" (
    "id" serial PRIMARY KEY NOT NULL,
    "email" text NOT NULL,
    "password_hash" text NOT NULL,
    CONSTRAINT "admin_users_email_unique" UNIQUE("email")
);

CREATE TABLE "exercises" (
    "id" serial PRIMARY KEY NOT NULL,
    "category" text NOT NULL,
    "title" text NOT NULL,
    "prompt" text NOT NULL,
    "difficulty" text NOT NULL,
    "config" text NOT NULL,
    "choices" text NOT NULL,
    "answer" text NOT NULL,
    "created_at" integer NOT NULL,
    "updated_at" integer NOT NULL,
    "explanation" text
);

CREATE TABLE "users" (
    "id" serial PRIMARY KEY NOT NULL,
    "email" text,
    "password_hash" text,
    "google_id" text,
    "name" text,
    "nickname" text,
    "avatar_url" text,
    "created_at" integer NOT NULL,
    CONSTRAINT "users_email_unique" UNIQUE("email"),
    CONSTRAINT "users_google_id_unique" UNIQUE("google_id")
);

CREATE TABLE "feedback" (
    "id" serial PRIMARY KEY NOT NULL,
    "user_id" integer,
    "name" text,
    "email" text,
    "message" text NOT NULL,
    "created_at" integer NOT NULL
);

CREATE TABLE "sessions" (
    "id" serial PRIMARY KEY NOT NULL,
    "session_token" text NOT NULL,
    "exercise_id" integer NOT NULL,
    "user_id" integer,
    "answered" text NOT NULL,
    "correct" boolean NOT NULL,
    "created_at" integer NOT NULL
);

CREATE TABLE "daily_puzzles" (
    "id" serial PRIMARY KEY NOT NULL,
    "puzzle_date" text NOT NULL,
    "category" text NOT NULL,
    "difficulty" text NOT NULL,
    "exercise_id" integer NOT NULL,
    "exercise_snapshot" text NOT NULL,
    "performance_params" text NOT NULL,
    "source" text DEFAULT 'pool' NOT NULL,
    "created_at" integer NOT NULL,
    CONSTRAINT "daily_puzzles_puzzle_date_unique" UNIQUE("puzzle_date")
);

CREATE TABLE "daily_attempts" (
    "id" serial PRIMARY KEY NOT NULL,
    "puzzle_id" integer NOT NULL,
    "user_id" integer,
    "session_token" text NOT NULL,
    "category" text NOT NULL,
    "difficulty" text NOT NULL,
    "exercise_id" integer NOT NULL,
    "exercise_type" text,
    "topic" text,
    "guesses" text DEFAULT '[]' NOT NULL,
    "status" text DEFAULT 'in_progress' NOT NULL,
    "final_guess_count" integer,
    "finished_at" integer,
    "created_at" integer NOT NULL,
    "updated_at" integer NOT NULL
);

ALTER TABLE "feedback" ADD CONSTRAINT "feedback_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_exercise_id_exercises_id_fk" FOREIGN KEY ("exercise_id") REFERENCES "public"."exercises"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "daily_puzzles" ADD CONSTRAINT "daily_puzzles_exercise_id_exercises_id_fk" FOREIGN KEY ("exercise_id") REFERENCES "public"."exercises"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "daily_attempts" ADD CONSTRAINT "daily_attempts_puzzle_id_daily_puzzles_id_fk" FOREIGN KEY ("puzzle_id") REFERENCES "public"."daily_puzzles"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "daily_attempts" ADD CONSTRAINT "daily_attempts_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "daily_attempts" ADD CONSTRAINT "daily_attempts_exercise_id_exercises_id_fk" FOREIGN KEY ("exercise_id") REFERENCES "public"."exercises"("id") ON DELETE restrict ON UPDATE no action;
CREATE UNIQUE INDEX "daily_attempts_user_puzzle_uq" ON "daily_attempts" USING btree ("puzzle_id","user_id") WHERE "daily_attempts"."user_id" is not null;
CREATE UNIQUE INDEX "daily_attempts_token_puzzle_uq" ON "daily_attempts" USING btree ("puzzle_id","session_token") WHERE "daily_attempts"."user_id" is null;
CREATE INDEX "daily_attempts_puzzle_idx" ON "daily_attempts" USING btree ("puzzle_id");
CREATE INDEX "daily_attempts_category_idx" ON "daily_attempts" USING btree ("category","status");
CREATE INDEX "daily_attempts_exercise_type_idx" ON "daily_attempts" USING btree ("exercise_type","status");

-- Exercise seed data


-- Reset sequences to avoid conflicts with future inserts
SELECT pg_catalog.setval('public.exercises_id_seq', 508, true);
SELECT pg_catalog.setval('public.admin_users_id_seq', 1, false);
