INSERT INTO public.exercises VALUES (574, 'chord', 'Major Chord', 'What type of chord is this?', 'easy', '{"type":"major"}', '["Major","Minor","Dominant 7th","Diminished"]', 'Major', 1783444284, 1783444284, 'A major chord is built from a root, major 3rd, and perfect 5th, giving it the bright, stable, ''happy'' sound that anchors most Western music. It''s the most common chord type and the natural resting point in a major key.');
INSERT INTO public.exercises VALUES (575, 'chord', 'Minor Chord', 'What type of chord is this?', 'easy', '{"type":"minor"}', '["Major","Minor","Dominant 7th","Diminished"]', 'Minor', 1783444284, 1783444284, 'A minor chord swaps the major 3rd for a minor 3rd, keeping the same root and perfect 5th. That single lowered note gives it a darker, more melancholic color, and it''s the natural resting point in a minor key.');
INSERT INTO public.exercises VALUES (576, 'chord', 'Dominant 7th', 'What type of chord is this?', 'easy', '{"type":"dom7"}', '["Major","Minor","Dominant 7th","Diminished"]', 'Dominant 7th', 1783444284, 1783444284, 'A dominant 7th chord is a major triad with a minor 7th added on top, creating tension that wants to resolve down a fifth to the tonic. It''s the defining sound of the V chord in both major and minor keys, and the backbone of blues and jazz.');
INSERT INTO public.exercises VALUES (577, 'chord', 'Diminished Triad', 'What type of chord is this?', 'easy', '{"type":"dim"}', '["Major","Minor","Dominant 7th","Diminished"]', 'Diminished', 1783444284, 1783444284, 'A diminished chord stacks two minor 3rds on top of each other, giving every interval in the chord a tense, unstable quality. It has no strong ''home'' feeling of its own and almost always functions as a passing or transitional chord resolving somewhere else.');
INSERT INTO public.exercises VALUES (578, 'chord', 'Major Chord', 'What type of chord is this?', 'medium', '{"type":"major"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented"]', 'Major', 1783444284, 1783444284, 'A major chord is built from a root, major 3rd, and perfect 5th, giving it the bright, stable, ''happy'' sound that anchors most Western music. It''s the most common chord type and the natural resting point in a major key.');
INSERT INTO public.exercises VALUES (579, 'chord', 'Minor Chord', 'What type of chord is this?', 'medium', '{"type":"minor"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented"]', 'Minor', 1783444284, 1783444284, 'A minor chord swaps the major 3rd for a minor 3rd, keeping the same root and perfect 5th. That single lowered note gives it a darker, more melancholic color, and it''s the natural resting point in a minor key.');
INSERT INTO public.exercises VALUES (580, 'chord', 'Dominant 7th', 'What type of chord is this?', 'medium', '{"type":"dom7"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented"]', 'Dominant 7th', 1783444284, 1783444284, 'A dominant 7th chord is a major triad with a minor 7th added on top, creating tension that wants to resolve down a fifth to the tonic. It''s the defining sound of the V chord in both major and minor keys, and the backbone of blues and jazz.');
INSERT INTO public.exercises VALUES (581, 'chord', 'Diminished Triad', 'What type of chord is this?', 'medium', '{"type":"dim"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented"]', 'Diminished', 1783444284, 1783444284, 'A diminished chord stacks two minor 3rds on top of each other, giving every interval in the chord a tense, unstable quality. It has no strong ''home'' feeling of its own and almost always functions as a passing or transitional chord resolving somewhere else.');
INSERT INTO public.exercises VALUES (582, 'chord', 'Major 7th', 'What type of chord is this?', 'medium', '{"type":"maj7"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented"]', 'Major 7th', 1783444284, 1783444284, 'A major 7th chord adds a major 7th on top of a major triad, one half-step below the octave. That extra note softens the chord''s brightness into something smoother and more sophisticated, giving it the dreamy, jazzy color heard in ballads and soul music.');
INSERT INTO public.exercises VALUES (583, 'chord', 'Minor 7th', 'What type of chord is this?', 'medium', '{"type":"min7"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented"]', 'Minor 7th', 1783444284, 1783444284, 'A minor 7th chord adds a minor 7th on top of a minor triad, blending the minor chord''s darker color with a smoother, less resolved quality than a plain minor triad. It''s a staple of jazz, R&B, and soul, especially in ii chords.');
INSERT INTO public.exercises VALUES (584, 'chord', 'Augmented Triad', 'What type of chord is this?', 'medium', '{"type":"aug"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented"]', 'Augmented', 1783444284, 1783444284, 'An augmented chord raises the 5th of a major triad by a half-step, so both outer intervals become major 3rds. That symmetry gives it a restless, unresolved, almost dreamlike quality, often used to create tension right before a resolution.');
INSERT INTO public.exercises VALUES (585, 'chord', 'Major Chord', 'What type of chord is this?', 'hard', '{"type":"major"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Major', 1783444284, 1783444284, 'A major chord is built from a root, major 3rd, and perfect 5th, giving it the bright, stable, ''happy'' sound that anchors most Western music. It''s the most common chord type and the natural resting point in a major key.');
INSERT INTO public.exercises VALUES (586, 'chord', 'Minor Chord', 'What type of chord is this?', 'hard', '{"type":"minor"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Minor', 1783444284, 1783444284, 'A minor chord swaps the major 3rd for a minor 3rd, keeping the same root and perfect 5th. That single lowered note gives it a darker, more melancholic color, and it''s the natural resting point in a minor key.');
INSERT INTO public.exercises VALUES (587, 'chord', 'Dominant 7th', 'What type of chord is this?', 'hard', '{"type":"dom7"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Dominant 7th', 1783444284, 1783444284, 'A dominant 7th chord is a major triad with a minor 7th added on top, creating tension that wants to resolve down a fifth to the tonic. It''s the defining sound of the V chord in both major and minor keys, and the backbone of blues and jazz.');
INSERT INTO public.exercises VALUES (588, 'chord', 'Diminished Triad', 'What type of chord is this?', 'hard', '{"type":"dim"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Diminished', 1783444284, 1783444284, 'A diminished chord stacks two minor 3rds on top of each other, giving every interval in the chord a tense, unstable quality. It has no strong ''home'' feeling of its own and almost always functions as a passing or transitional chord resolving somewhere else.');
INSERT INTO public.exercises VALUES (589, 'chord', 'Major 7th', 'What type of chord is this?', 'hard', '{"type":"maj7"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Major 7th', 1783444284, 1783444284, 'A major 7th chord adds a major 7th on top of a major triad, one half-step below the octave. That extra note softens the chord''s brightness into something smoother and more sophisticated, giving it the dreamy, jazzy color heard in ballads and soul music.');
INSERT INTO public.exercises VALUES (590, 'chord', 'Minor 7th', 'What type of chord is this?', 'hard', '{"type":"min7"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Minor 7th', 1783444284, 1783444284, 'A minor 7th chord adds a minor 7th on top of a minor triad, blending the minor chord''s darker color with a smoother, less resolved quality than a plain minor triad. It''s a staple of jazz, R&B, and soul, especially in ii chords.');
INSERT INTO public.exercises VALUES (591, 'chord', 'Augmented Triad', 'What type of chord is this?', 'hard', '{"type":"aug"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Augmented', 1783444284, 1783444284, 'An augmented chord raises the 5th of a major triad by a half-step, so both outer intervals become major 3rds. That symmetry gives it a restless, unresolved, almost dreamlike quality, often used to create tension right before a resolution.');
INSERT INTO public.exercises VALUES (592, 'chord', 'Diminished 7th', 'What type of chord is this?', 'hard', '{"type":"dim7"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Diminished 7th', 1783444284, 1783444284, 'A diminished 7th chord stacks three minor 3rds in a row, dividing the octave perfectly evenly into four equal parts. That symmetry makes it maximally unstable and highly flexible for modulating between distant keys, a favorite trick in classical and jazz harmony.');
INSERT INTO public.exercises VALUES (593, 'chord', 'Half-Diminished 7th', 'What type of chord is this?', 'hard', '{"type":"min7b5"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Half-Diminished', 1783444284, 1783444284, 'A half-diminished chord (m7♭5) is a diminished triad with a minor 7th added instead of a diminished 7th, making it slightly less tense than a fully diminished chord. It''s best known as the ii chord in minor-key ii-V-i progressions in jazz.');
INSERT INTO public.exercises VALUES (594, 'chord', 'Major 9th', 'What type of chord is this?', 'hard', '{"type":"maj9"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Major 9th', 1783444284, 1783444284, 'A major 9th chord extends a major 7th chord by adding the 9th (the 2nd scale degree, an octave up). That extra color note makes an already smooth major 7th sound even richer and more lush, common in jazz, neo-soul, and R&B.');
INSERT INTO public.exercises VALUES (595, 'chord', 'Minor 9th', 'What type of chord is this?', 'hard', '{"type":"min9"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Minor 9th', 1783444284, 1783444284, 'A minor 9th chord extends a minor 7th chord by adding the 9th on top, layering extra color onto its already dark, smooth sound. It''s widely used in jazz and neo-soul for a lush, sophisticated minor-key texture.');
INSERT INTO public.exercises VALUES (596, 'chord', 'Major 6th', 'What type of chord is this?', 'hard', '{"type":"maj6"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Major 6th', 1783444284, 1783444284, 'A major 6th chord replaces a major 7th chord''s 7th with the 6th scale degree instead, giving it a bright, open, slightly retro sound without the 7th''s tension. It was a signature sound of swing-era and early jazz endings.');
INSERT INTO public.exercises VALUES (597, 'chord', 'Minor 6th', 'What type of chord is this?', 'hard', '{"type":"min6"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Minor 6th', 1783444284, 1783444284, 'A minor 6th chord adds the 6th scale degree (rather than a 7th) on top of a minor triad, giving it a slightly unresolved, wistful color distinct from a plain minor 7th. It shows up often in jazz and film-score minor-key passages.');
INSERT INTO public.exercises VALUES (598, 'chord', 'Suspended 4th', 'What type of chord is this?', 'hard', '{"type":"sus4"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Sus4', 1783444284, 1783444284, 'A suspended 4th chord replaces a chord''s 3rd with a 4th, removing the note that normally defines whether a chord is major or minor. That missing 3rd creates an open, floating tension that usually wants to resolve back down to the 3rd.');
INSERT INTO public.exercises VALUES (599, 'chord', 'Suspended 9th', 'What type of chord is this?', 'hard', '{"type":"sus9"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Sus9', 1783444284, 1783444284, 'A sus9 chord (also called 9sus4) replaces a dominant 9th chord''s 3rd with a 4th, keeping the 7th and 9th on top. It has an open, ambiguous quality that avoids resolving to major or minor, often used in modern pop and jazz as a color chord on its own rather than a passing suspension.');
INSERT INTO public.exercises VALUES (600, 'chord', 'Major add2', 'What type of chord is this?', 'hard', '{"type":"add2"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Major add2', 1783444284, 1783444284, 'A major add2 chord adds the 2nd scale degree on top of a plain major triad, without removing the 3rd (unlike a sus2 chord, which replaces it). That extra note adds a bright, open, slightly modern color while keeping the chord clearly major, common in pop and contemporary singer-songwriter music.');
INSERT INTO public.exercises VALUES (601, 'chord', 'Major add4', 'What type of chord is this?', 'hard', '{"type":"add4"}', '["Major","Minor","Dominant 7th","Diminished","Major 7th","Minor 7th","Augmented","Diminished 7th","Half-Diminished","Major 9th","Minor 9th","Major 6th","Minor 6th","Sus4","Sus9","Major add2","Major add4"]', 'Major add4', 1783444284, 1783444284, 'A major add4 chord adds the perfect 4th on top of a plain major triad, without removing the 3rd (unlike a sus4 chord, which replaces it). The 3rd and 4th sitting a half-step apart create a bit of inner tension, giving the chord a bright but slightly unresolved, open color.');
INSERT INTO public.exercises VALUES (602, 'chord', 'Major Chord — 1st Inversion', 'What chord and inversion is this?', 'medium', '{"type":"major","inversion":1,"topic":"inversions"}', '["Major - Root Position","Major - 1st Inversion","Major - 2nd Inversion","Minor - Root Position","Minor - 1st Inversion","Minor - 2nd Inversion"]', 'Major - 1st Inversion', 1783444284, 1783444284, 'A major chord is built from a root, major 3rd, and perfect 5th, giving it the bright, stable, ''happy'' sound that anchors most Western music. It''s the most common chord type and the natural resting point in a major key.');
INSERT INTO public.exercises VALUES (603, 'chord', 'Major Chord — 2nd Inversion', 'What chord and inversion is this?', 'medium', '{"type":"major","inversion":2,"topic":"inversions"}', '["Major - Root Position","Major - 1st Inversion","Major - 2nd Inversion","Minor - Root Position","Minor - 1st Inversion","Minor - 2nd Inversion"]', 'Major - 2nd Inversion', 1783444284, 1783444284, 'A major chord is built from a root, major 3rd, and perfect 5th, giving it the bright, stable, ''happy'' sound that anchors most Western music. It''s the most common chord type and the natural resting point in a major key.');
INSERT INTO public.exercises VALUES (604, 'chord', 'Minor Chord — 1st Inversion', 'What chord and inversion is this?', 'medium', '{"type":"minor","inversion":1,"topic":"inversions"}', '["Major - Root Position","Major - 1st Inversion","Major - 2nd Inversion","Minor - Root Position","Minor - 1st Inversion","Minor - 2nd Inversion"]', 'Minor - 1st Inversion', 1783444284, 1783444284, 'A minor chord swaps the major 3rd for a minor 3rd, keeping the same root and perfect 5th. That single lowered note gives it a darker, more melancholic color, and it''s the natural resting point in a minor key.');
INSERT INTO public.exercises VALUES (605, 'chord', 'Minor Chord — 2nd Inversion', 'What chord and inversion is this?', 'medium', '{"type":"minor","inversion":2,"topic":"inversions"}', '["Major - Root Position","Major - 1st Inversion","Major - 2nd Inversion","Minor - Root Position","Minor - 1st Inversion","Minor - 2nd Inversion"]', 'Minor - 2nd Inversion', 1783444284, 1783444284, 'A minor chord swaps the major 3rd for a minor 3rd, keeping the same root and perfect 5th. That single lowered note gives it a darker, more melancholic color, and it''s the natural resting point in a minor key.');
INSERT INTO public.exercises VALUES (606, 'chord', 'Dominant 7th Chord — Root Position', 'What chord and inversion is this?', 'hard', '{"type":"dom7","inversion":0,"topic":"inversions"}', '["Dominant 7th - Root Position","Dominant 7th - 1st Inversion","Dominant 7th - 2nd Inversion","Dominant 7th - 3rd Inversion","Major 7th - Root Position","Minor 7th - Root Position"]', 'Dominant 7th - Root Position', 1783444284, 1783444284, 'A dominant 7th chord is a major triad with a minor 7th added on top, creating tension that wants to resolve down a fifth to the tonic. It''s the defining sound of the V chord in both major and minor keys, and the backbone of blues and jazz.');
INSERT INTO public.exercises VALUES (607, 'chord', 'Dominant 7th Chord — 1st Inversion', 'What chord and inversion is this?', 'hard', '{"type":"dom7","inversion":1,"topic":"inversions"}', '["Dominant 7th - Root Position","Dominant 7th - 1st Inversion","Dominant 7th - 2nd Inversion","Dominant 7th - 3rd Inversion","Major 7th - 1st Inversion","Minor 7th - 1st Inversion"]', 'Dominant 7th - 1st Inversion', 1783444284, 1783444284, 'A dominant 7th chord is a major triad with a minor 7th added on top, creating tension that wants to resolve down a fifth to the tonic. It''s the defining sound of the V chord in both major and minor keys, and the backbone of blues and jazz.');
INSERT INTO public.exercises VALUES (608, 'chord', 'Dominant 7th Chord — 2nd Inversion', 'What chord and inversion is this?', 'hard', '{"type":"dom7","inversion":2,"topic":"inversions"}', '["Dominant 7th - Root Position","Dominant 7th - 1st Inversion","Dominant 7th - 2nd Inversion","Dominant 7th - 3rd Inversion","Major 7th - 2nd Inversion","Minor 7th - 2nd Inversion"]', 'Dominant 7th - 2nd Inversion', 1783444284, 1783444284, 'A dominant 7th chord is a major triad with a minor 7th added on top, creating tension that wants to resolve down a fifth to the tonic. It''s the defining sound of the V chord in both major and minor keys, and the backbone of blues and jazz.');
INSERT INTO public.exercises VALUES (609, 'chord', 'Dominant 7th Chord — 3rd Inversion', 'What chord and inversion is this?', 'hard', '{"type":"dom7","inversion":3,"topic":"inversions"}', '["Dominant 7th - Root Position","Dominant 7th - 1st Inversion","Dominant 7th - 2nd Inversion","Dominant 7th - 3rd Inversion","Major 7th - 3rd Inversion","Minor 7th - 3rd Inversion"]', 'Dominant 7th - 3rd Inversion', 1783444284, 1783444284, 'A dominant 7th chord is a major triad with a minor 7th added on top, creating tension that wants to resolve down a fifth to the tonic. It''s the defining sound of the V chord in both major and minor keys, and the backbone of blues and jazz.');
INSERT INTO public.exercises VALUES (610, 'chord', 'Major 7th Chord — Root Position', 'What chord and inversion is this?', 'hard', '{"type":"maj7","inversion":0,"topic":"inversions"}', '["Major 7th - Root Position","Major 7th - 1st Inversion","Major 7th - 2nd Inversion","Major 7th - 3rd Inversion","Dominant 7th - Root Position","Minor 7th - Root Position"]', 'Major 7th - Root Position', 1783444284, 1783444284, 'A major 7th chord adds a major 7th on top of a major triad, one half-step below the octave. That extra note softens the chord''s brightness into something smoother and more sophisticated, giving it the dreamy, jazzy color heard in ballads and soul music.');
INSERT INTO public.exercises VALUES (611, 'chord', 'Major 7th Chord — 1st Inversion', 'What chord and inversion is this?', 'hard', '{"type":"maj7","inversion":1,"topic":"inversions"}', '["Major 7th - Root Position","Major 7th - 1st Inversion","Major 7th - 2nd Inversion","Major 7th - 3rd Inversion","Dominant 7th - 1st Inversion","Minor 7th - 1st Inversion"]', 'Major 7th - 1st Inversion', 1783444284, 1783444284, 'A major 7th chord adds a major 7th on top of a major triad, one half-step below the octave. That extra note softens the chord''s brightness into something smoother and more sophisticated, giving it the dreamy, jazzy color heard in ballads and soul music.');
INSERT INTO public.exercises VALUES (612, 'chord', 'Major 7th Chord — 2nd Inversion', 'What chord and inversion is this?', 'hard', '{"type":"maj7","inversion":2,"topic":"inversions"}', '["Major 7th - Root Position","Major 7th - 1st Inversion","Major 7th - 2nd Inversion","Major 7th - 3rd Inversion","Dominant 7th - 2nd Inversion","Minor 7th - 2nd Inversion"]', 'Major 7th - 2nd Inversion', 1783444284, 1783444284, 'A major 7th chord adds a major 7th on top of a major triad, one half-step below the octave. That extra note softens the chord''s brightness into something smoother and more sophisticated, giving it the dreamy, jazzy color heard in ballads and soul music.');
INSERT INTO public.exercises VALUES (613, 'chord', 'Major 7th Chord — 3rd Inversion', 'What chord and inversion is this?', 'hard', '{"type":"maj7","inversion":3,"topic":"inversions"}', '["Major 7th - Root Position","Major 7th - 1st Inversion","Major 7th - 2nd Inversion","Major 7th - 3rd Inversion","Dominant 7th - 3rd Inversion","Minor 7th - 3rd Inversion"]', 'Major 7th - 3rd Inversion', 1783444284, 1783444284, 'A major 7th chord adds a major 7th on top of a major triad, one half-step below the octave. That extra note softens the chord''s brightness into something smoother and more sophisticated, giving it the dreamy, jazzy color heard in ballads and soul music.');
INSERT INTO public.exercises VALUES (614, 'chord', 'Minor 7th Chord — Root Position', 'What chord and inversion is this?', 'hard', '{"type":"min7","inversion":0,"topic":"inversions"}', '["Minor 7th - Root Position","Minor 7th - 1st Inversion","Minor 7th - 2nd Inversion","Minor 7th - 3rd Inversion","Major 7th - Root Position","Dominant 7th - Root Position"]', 'Minor 7th - Root Position', 1783444284, 1783444284, 'A minor 7th chord adds a minor 7th on top of a minor triad, blending the minor chord''s darker color with a smoother, less resolved quality than a plain minor triad. It''s a staple of jazz, R&B, and soul, especially in ii chords.');
INSERT INTO public.exercises VALUES (615, 'chord', 'Minor 7th Chord — 1st Inversion', 'What chord and inversion is this?', 'hard', '{"type":"min7","inversion":1,"topic":"inversions"}', '["Minor 7th - Root Position","Minor 7th - 1st Inversion","Minor 7th - 2nd Inversion","Minor 7th - 3rd Inversion","Major 7th - 1st Inversion","Dominant 7th - 1st Inversion"]', 'Minor 7th - 1st Inversion', 1783444284, 1783444284, 'A minor 7th chord adds a minor 7th on top of a minor triad, blending the minor chord''s darker color with a smoother, less resolved quality than a plain minor triad. It''s a staple of jazz, R&B, and soul, especially in ii chords.');
INSERT INTO public.exercises VALUES (616, 'chord', 'Minor 7th Chord — 2nd Inversion', 'What chord and inversion is this?', 'hard', '{"type":"min7","inversion":2,"topic":"inversions"}', '["Minor 7th - Root Position","Minor 7th - 1st Inversion","Minor 7th - 2nd Inversion","Minor 7th - 3rd Inversion","Major 7th - 2nd Inversion","Dominant 7th - 2nd Inversion"]', 'Minor 7th - 2nd Inversion', 1783444284, 1783444284, 'A minor 7th chord adds a minor 7th on top of a minor triad, blending the minor chord''s darker color with a smoother, less resolved quality than a plain minor triad. It''s a staple of jazz, R&B, and soul, especially in ii chords.');
INSERT INTO public.exercises VALUES (617, 'chord', 'Minor 7th Chord — 3rd Inversion', 'What chord and inversion is this?', 'hard', '{"type":"min7","inversion":3,"topic":"inversions"}', '["Minor 7th - Root Position","Minor 7th - 1st Inversion","Minor 7th - 2nd Inversion","Minor 7th - 3rd Inversion","Major 7th - 3rd Inversion","Dominant 7th - 3rd Inversion"]', 'Minor 7th - 3rd Inversion', 1783444284, 1783444284, 'A minor 7th chord adds a minor 7th on top of a minor triad, blending the minor chord''s darker color with a smoother, less resolved quality than a plain minor triad. It''s a staple of jazz, R&B, and soul, especially in ii chords.');
INSERT INTO public.exercises VALUES (618, 'chord', 'Diminished 7th Chord — Root Position', 'What chord and inversion is this?', 'hard', '{"type":"dim7","inversion":0,"topic":"inversions"}', '["Diminished 7th - Root Position","Diminished 7th - 1st Inversion","Diminished 7th - 2nd Inversion","Diminished 7th - 3rd Inversion","Half-Diminished - Root Position","Minor 7th - Root Position"]', 'Diminished 7th - Root Position', 1783444284, 1783444284, 'A diminished 7th chord stacks three minor 3rds in a row, dividing the octave perfectly evenly into four equal parts. That symmetry makes it maximally unstable and highly flexible for modulating between distant keys, a favorite trick in classical and jazz harmony.');
INSERT INTO public.exercises VALUES (619, 'chord', 'Diminished 7th Chord — 1st Inversion', 'What chord and inversion is this?', 'hard', '{"type":"dim7","inversion":1,"topic":"inversions"}', '["Diminished 7th - Root Position","Diminished 7th - 1st Inversion","Diminished 7th - 2nd Inversion","Diminished 7th - 3rd Inversion","Half-Diminished - 1st Inversion","Minor 7th - 1st Inversion"]', 'Diminished 7th - 1st Inversion', 1783444284, 1783444284, 'A diminished 7th chord stacks three minor 3rds in a row, dividing the octave perfectly evenly into four equal parts. That symmetry makes it maximally unstable and highly flexible for modulating between distant keys, a favorite trick in classical and jazz harmony.');
INSERT INTO public.exercises VALUES (620, 'chord', 'Diminished 7th Chord — 2nd Inversion', 'What chord and inversion is this?', 'hard', '{"type":"dim7","inversion":2,"topic":"inversions"}', '["Diminished 7th - Root Position","Diminished 7th - 1st Inversion","Diminished 7th - 2nd Inversion","Diminished 7th - 3rd Inversion","Half-Diminished - 2nd Inversion","Minor 7th - 2nd Inversion"]', 'Diminished 7th - 2nd Inversion', 1783444284, 1783444284, 'A diminished 7th chord stacks three minor 3rds in a row, dividing the octave perfectly evenly into four equal parts. That symmetry makes it maximally unstable and highly flexible for modulating between distant keys, a favorite trick in classical and jazz harmony.');
INSERT INTO public.exercises VALUES (621, 'chord', 'Diminished 7th Chord — 3rd Inversion', 'What chord and inversion is this?', 'hard', '{"type":"dim7","inversion":3,"topic":"inversions"}', '["Diminished 7th - Root Position","Diminished 7th - 1st Inversion","Diminished 7th - 2nd Inversion","Diminished 7th - 3rd Inversion","Half-Diminished - 3rd Inversion","Minor 7th - 3rd Inversion"]', 'Diminished 7th - 3rd Inversion', 1783444284, 1783444284, 'A diminished 7th chord stacks three minor 3rds in a row, dividing the octave perfectly evenly into four equal parts. That symmetry makes it maximally unstable and highly flexible for modulating between distant keys, a favorite trick in classical and jazz harmony.');
INSERT INTO public.exercises VALUES (622, 'chord', 'Half-Diminished Chord — Root Position', 'What chord and inversion is this?', 'hard', '{"type":"min7b5","inversion":0,"topic":"inversions"}', '["Half-Diminished - Root Position","Half-Diminished - 1st Inversion","Half-Diminished - 2nd Inversion","Half-Diminished - 3rd Inversion","Diminished 7th - Root Position","Minor 7th - Root Position"]', 'Half-Diminished - Root Position', 1783444284, 1783444284, 'A half-diminished chord (m7♭5) is a diminished triad with a minor 7th added instead of a diminished 7th, making it slightly less tense than a fully diminished chord. It''s best known as the ii chord in minor-key ii-V-i progressions in jazz.');
